def data_path():
    return authored([dict(position=[0,0,100],orientation=[0,0,0],duration=2),dict(position=[0,0,100],orientation=[0,0,90])],True).encode()


class Closure(TestCase):
    @classmethod
    def setUpClass(cls):
        cls.app=QApplication.instance() or QApplication([]);cls.backend=Backend(Workspace(ROOT,GAME));cls.backend.safe_mode=True

    def valid(self,root):
        result=self.backend.validate(root);self.assertTrue(result.valid,[p.message for p in result.problems]);return result.project

    def zones(self,dynamic=False):
        root=fixture(dynamic);root['chronicle']['id']='final_test';root['state']['flags']['ambience']=207
        scene=root['scenes'][0]
        wav=next(e['id'] for e in self.backend.resources['entries'] if e['extension'].lower()=='.wav')
        light=dict(entity='mentor',color=[1,1,1],intensity=1,radius=200,style='constant')
        scene['triggers']=[dict(id='ambience',name='Interactive ambience',shape='box',size=[100,100,100],transform=copy.deepcopy(scene['entries'][0]['transform']),zone_flag=dict(flag='ambience',is_set=True),sound_zone=dict(resource=wav,volume=25,min_distance=64,max_distance=300),light_zone=light)]
        return root

    def test_original_player_links_are_placed_companions_not_current_lan_player(self):
        evidence=json.loads((ROOT/'research/authoring_completion/final_original_evidence.json').read_text())
        self.assertEqual({r['player_links'][0]['target_template'].lower() for r in evidence['scenes']},{'erik','samuel','serena','pink','wilhem','wilhemmod'})
        self.assertEqual(len(evidence['player_classes']),6)
        with zipfile.ZipFile(GAME/'Codex.nob') as archive:
            for row in evidence['player_classes']:
                data=archive.read(row['class_']+'.class')
                self.assertEqual(hashlib.sha256(data).hexdigest(),row['sha256'])
                self.assertTrue(row['chronicle_casts'])
                self.assertEqual(constructors(data),[])  # No unsafe live-player reinterpretation.
        self.assertEqual(set(evidence['entity_reference_switch'].values()),{0x4b5347})

    def test_zone_gate_validation_reference_rename_and_formats_roundtrip(self):
        for dynamic in (False,True):
            root=self.zones(dynamic);self.valid(root)
            with tempfile.TemporaryDirectory(dir=ROOT/'build/tests') as folder:
                doc=CampaignDocument(self.backend.ws,root,Path(folder)/'project.yaml')
                links=graph(root)
                self.assertTrue(any(link.detail[-2:]==('zone_flag','flag') for link in links))
                doc.rename_flag('ambience','ambient_new');self.valid(doc.snapshot())
                self.assertEqual(doc.campaign['scenes'][0]['triggers'][0]['zone_flag']['flag'],'ambient_new')
                doc.save();loaded=CampaignDocument.load(self.backend.ws,doc.path)
                self.assertEqual(loaded.snapshot(),doc.snapshot())
        for gate in ({'flag':'missing','is_set':True},{'flag':'ambience','is_set':1}):
            root=self.zones();root['scenes'][0]['triggers'][0]['zone_flag']=gate
            self.assertFalse(self.backend.validate(root).valid)

    def test_zone_rejects_duplicate_or_native_owners(self):
        root=self.zones();scene=root['scenes'][0];second=copy.deepcopy(scene['triggers'][0]);second['id']='second';scene['triggers'].append(second)
        self.assertFalse(self.backend.validate(root).valid)
        root=self.zones();scene=root['scenes'][0];scene['waypoints']=[dict(id='frame',name='Frame',transform=copy.deepcopy(scene['entries'][0]['transform']))]
        mentor=next(a for a in scene['actors'] if a['id']=='mentor');mentor['native_frames']=['frame'];mentor.pop('conversation',None)
        result=self.backend.validate(root);self.assertFalse(result.valid)
        self.assertTrue(any('native-owned' in p.message for p in result.problems))

    def test_flag_rename_rewrites_inactive_scene_zones_and_event_actions(self):
        root=self.zones();other=copy.deepcopy(root['scenes'][0]);other['id']='second'
        other['events'].append(dict(id='switch_off',when='manual',actions=[dict(clear_flag='ambience')]))
        root['scenes'].append(other);self.valid(root)
        doc=CampaignDocument(self.backend.ws,root);doc.rename_flag('ambience','ambient_new');self.valid(doc.snapshot())
        for scene in doc.campaign['scenes']:self.assertEqual(scene['triggers'][0]['zone_flag']['flag'],'ambient_new')
        self.assertEqual(doc.campaign['scenes'][1]['events'][-1]['actions'],[dict(clear_flag='ambient_new')])

    def test_combined_zone_eax_dynamic_camera_compiles_against_real_codex(self):
        root=self.zones(True);scene=root['scenes'][0];scene['level']['environment']={'room_type':4}
        light=scene['triggers'][0]['light_zone'];light['entity']='dynamic/boss/boss/0'
        scene['sequences']=[dict(id='boss_view',name='Boss camera',actor='dynamic/boss/boss/0',duration=3,shot='medium',angle='high')]
        scene['events'].append(dict(id='observe',when='manual',actions=[dict(play_sequence='boss_view')]))
        campaign=self.valid(root);report=self.backend.build(root)
        self.assertEqual(set(report['class_versions'].values()),{'45.3'})
        code=runtime(campaign,*campaign.scenes[0])[1]
        self.assertIn('dynamicRoleOwns(',code);self.assertIn('roomtype ',code)
        self.assertIn('CodexSequence.GetChronicleFlag(207)',code)
        self.assertIn('releaseSceneLights();',code)

    def test_generated_bytecode_zone_flags_overrides_save_reentry_and_foreign_guid(self):
        root=self.zones();scene=root['scenes'][0]
        manual=dict(scene['triggers'][0]['light_zone'],color=[0,0,1])
        scene['events'].append(dict(id='blue',when='manual',actions=[dict(set_dynamic_light=manual)]))
        campaign=self.valid(root);name=runtime(campaign,*campaign.scenes[0])[0]
        target_index=next(i for i,e in enumerate(campaign.scenes[0][1].entities) if e.id=='mentor')
        command=configurations(scene)[0].index({'set_dynamic_light':manual})
        pos=scene['entries'][0]['transform']['position'];vector=','.join(str(float(v))+'f' for v in pos)
        harness='''public class StabilityHarness {
 static void tick(SCENE s){s.timer(9400,0,0,0,0);}
 static void check(boolean b,String message){if(!b)throw new AssertionError(message);}
 public static void main(String[] args)throws Exception {
 CE.Thing p=new CE.Thing();p.template="player";CE.world.put(1,p);SCENE s=new SCENE();s.beginscene(1,0);
 java.lang.reflect.Field things=SCENE.class.getDeclaredField("things");things.setAccessible(true);int guid=((int[])things.get(s))[TARGET_INDEX];
 CE.colours.put(Integer.valueOf(guid),Float.valueOf(8));tick(s);check(CE.colours.get(Integer.valueOf(guid)).floatValue()==8,"outside zone cleared an existing light");
 CE.world.get(1).pos=new float[]{POSITION};CodexSequence.SetChronicleFlag(207);tick(s);check(CE.liveSounds==1,"missing zone loop");check(CE.colours.get(Integer.valueOf(guid)).floatValue()==1,"missing zone light");
 int starts=CE.soundStarts,allocs=CE.allocs;for(int i=0;i<5;i++)tick(s);check(CE.soundStarts==starts && CE.allocs==allocs,"repeated handles");
 java.lang.reflect.Method light=SCENE.class.getDeclaredMethod("sceneLight",new Class[]{Integer.TYPE});light.setAccessible(true);light.invoke(s,new Object[]{Integer.valueOf(COMMAND)});tick(s);check(CE.colours.get(Integer.valueOf(guid)).floatValue()==0,"zone overwrote an event");
 CE.save.clear();s.save(0);CE.read=0;s.restore(0);s.beginscene(1,0);tick(s);check(CE.liveSounds==1 && CE.maxSounds==1,"restore duplicated loop");check(CE.colours.get(Integer.valueOf(guid)).floatValue()==0,"restore overwrote manual light");
 CodexSequence.ClearChronicleFlag(207);tick(s);check(CE.liveSounds==0,"flag did not interrupt sound");check(CE.colours.containsKey(Integer.valueOf(guid)),"zone cleared later event light");
 CodexSequence.SetChronicleFlag(207);tick(s);check(CE.liveSounds==1 && CE.colours.get(Integer.valueOf(guid)).floatValue()==1,"zone did not reactivate");
 CE.world.get(1).pos=new float[]{99999,99999,99999};tick(s);check(CE.liveSounds==0 && !CE.colours.containsKey(Integer.valueOf(guid)),"exit leaked zone resources");
 CE.world.get(1).pos=new float[]{POSITION};tick(s);s.endscene(1,0,0);check(CE.liveSounds==0 && !CE.colours.containsKey(Integer.valueOf(guid)),"scene end leaked resources");
 s.beginscene(1,0);tick(s);check(CE.liveSounds==1,"reentry failed");
 CE.world.get(guid).template="foreign";CE.colours.put(Integer.valueOf(guid),Float.valueOf(9));s.endscene(1,0,0);check(CE.colours.get(Integer.valueOf(guid)).floatValue()==9,"cleanup cleared a foreign template");
 }}'''.replace('SCENE',name).replace('POSITION',vector).replace('COMMAND',str(command)).replace('TARGET_INDEX',str(target_index))
        def doubles(text):
            text=text.replace('class CE {','class CE {static java.util.Map<Integer,Float> colours=new java.util.HashMap<Integer,Float>();static int liveSounds=0,maxSounds=0,soundStarts=0,allocs=0;')
            text=text.replace('class Codex {','class Codex {static final int SOUND_FLAG_LOOP=1,LIGHTSTYLE_CONSTANT=0;')
            text=text.replace('class CodexThing extends Codex {','class CodexThing extends Codex {boolean AllocateDynamicLight(){CE.allocs++;return true;}boolean ClearDynamicLight(){CE.colours.remove(Integer.valueOf(guid));return true;}boolean SetDynamicLightColor(float[] v){CE.colours.put(Integer.valueOf(guid),Float.valueOf(v[0]));return true;}boolean SetDynamicLightIntensity(float v){return true;}boolean SetDynamicLightRadius(float v){return true;}boolean SetDynamicLightStyle(int v){return true;}')
            return text.replace('class CodexSound extends Codex {','class CodexSound extends Codex {boolean stopped=false;CodexSound(String n,float a,float b,int v,int p,int f,float[] pos){CE.soundStarts++;CE.liveSounds++;CE.maxSounds=Math.max(CE.maxSounds,CE.liveSounds);}void Stop(){if(!stopped){CE.liveSounds--;stopped=true;}}')
        with tempfile.TemporaryDirectory(dir=ROOT/'build/tests') as tmp:
            compile_scenario(Path(tmp),campaign,harness,doubles)
            run=subprocess.run(['java','-cp',tmp,'StabilityHarness'],capture_output=True,text=True,timeout=30)
            self.assertEqual(run.returncode,0,run.stdout+run.stderr)

    def test_zone_ui_apply_cancel_undo_save_and_reopen(self):
        from rcm.editor.window import MainWindow
        from rcm.editor.zones import edit_zone
        root=self.zones();root['scenes'][0]['triggers'][0].pop('zone_flag');win=MainWindow(self.backend);win.doc=CampaignDocument(self.backend.ws,root);win.refresh();before=win.doc.snapshot()
        try:
            def interact(accept):
                dialog=next(d for d in win.findChildren(QDialog) if d.isVisible() and d.findChild(QComboBox,'zone_flag'))
                flag=dialog.findChild(QComboBox,'zone_flag');flag.setCurrentIndex(flag.findData('ambience'))
                dialog.findChild(QCheckBox,'zone_flag_value').setChecked(False)
                dialog.findChild(QDialogButtonBox).button(QDialogButtonBox.StandardButton.Ok if accept else QDialogButtonBox.StandardButton.Cancel).click()
            QTimer.singleShot(0,lambda:interact(False));edit_zone(win,win.doc.data['triggers'][0],'sound');self.assertEqual(win.doc.snapshot(),before)
            QTimer.singleShot(0,lambda:interact(True));edit_zone(win,win.doc.data['triggers'][0],'sound');after=win.doc.snapshot();self.valid(after)
            self.assertEqual(after['scenes'][0]['triggers'][0]['zone_flag'],dict(flag='ambience',is_set=False))
            win.undo_project();self.assertEqual(win.doc.snapshot(),before);win.redo_project();self.assertEqual(win.doc.snapshot(),after)
        finally:win.doc=None;win.close();self.app.processEvents()

    def test_data_only_library_import_and_safe_code_exclusion(self):
        case=library_tests.ContentLibraries();case.setUp()
        try:
            source=case.ws.write('assets.nob',zip_bytes({'camera/QuietTurn.ncp':data_path(),'codex/Evil.class':b'bad','chronicles/No.nsc':b'bad'}))
            self.assertEqual(asset_preview(source),['camera/QuietTurn.ncp'])
            data,record=prepare_import(case.ws,source,None,[],case.base,['camera/QuietTurn.ncp'])
            self.assertIsNone(record['not_path']);self.assertEqual(record['templates'],[])
            with zipfile.ZipFile(io.BytesIO(data)) as archive:self.assertEqual(archive.namelist(),['camera/QuietTurn.ncp'])
            imported=import_content(case.backend(),source,None,[],['camera/QuietTurn.ncp'])
            for used in ({'camera_path':'QuietTurn'},{'play_camera_path':{'resource':'QuietTurn'}},{'sound_zone':{'resource':'QuietTurn'}},{'start_music':'QuietTurn'},{'start_ambient':'QuietTurn'}):
                with self.assertRaises(ValueError):remove_content(case.backend(),imported['id'],used)
            self.assertEqual(imported['id'],record['id'])
            remove_content(case.backend(),imported['id'])
        finally:case.tearDown()

    def test_data_only_camera_library_build_save_reopen_and_distribution(self):
        with tempfile.TemporaryDirectory(dir=ROOT/'build/tests') as tmp:
            ws=Workspace(Path(tmp),GAME)
            for name in ('levels','resources','scene_hints'):ws.write('cache/'+name+'.json',(ROOT/'cache'/(name+'.json')).read_bytes())
            for folder in ('Chronicles','Codex.nob'):
                shutil.copytree(ROOT/'research/original'/folder,ws.output('research/original/'+folder))
            for name in self.backend.levels['EastLondon']['scenes']:
                entry=self.backend.hints[name.casefold()]['source'];rel='research/original/'+entry['archive']+'/'+entry['path'];ws.write(rel,(ROOT/rel).read_bytes())
            for name in ('classes.zip','ecj-3.26.0.jar'):ws.write('cache/toolchain/'+name,(ROOT/'cache/toolchain'/name).read_bytes())
            backend=Backend(ws);source=ws.write('paths.nob',zip_bytes({'camera/QuietTurn.ncp':data_path()}));original=source.read_bytes()
            record=import_content(backend,source,None,[],['camera/QuietTurn.ncp'])
            root=fixture();root['chronicle']['id']='import_path'
            root['scenes'][0]['sequences']=[dict(id='turn',name='Turn',actor='mentor',duration=2,shot='medium',angle='high',camera_path='QuietTurn')]
            doc=CampaignDocument(ws,root,ws.output('chronicles/path/project.yaml'));doc.save();loaded=CampaignDocument.load(ws,doc.path)
            self.assertEqual(loaded.snapshot(),root)
            report=backend.build(loaded.snapshot());self.assertEqual(set(report['class_versions'].values()),{'45.3'})
            self.assertEqual(report['local_libraries'][0]['id'],record['id'])
            with zipfile.ZipFile(ws.output('build/import_path/import_path.nob')) as archive:
                nmf=archive.read('chronicles/R_import_path.nmf').decode('cp1252');self.assertNotIn('None',nmf)
            with zipfile.ZipFile(ws.output('build/import_path/import_path_distribution.zip')) as archive:self.assertNotIn(record['archive'],archive.namelist())
            self.assertEqual(source.read_bytes(),original)

    def test_dynamic_light_zone_target_is_selectable_and_undoable_in_qt(self):
        from rcm.editor.window import MainWindow
        from rcm.editor.zones import edit_zone
        root=self.zones(True);win=MainWindow(self.backend);win.doc=CampaignDocument(self.backend.ws,root);win.refresh();before=win.doc.snapshot()
        try:
            def select():
                dialog=next(d for d in win.findChildren(QDialog) if d.isVisible() and d.findChild(QComboBox,'zone_entity'))
                combo=dialog.findChild(QComboBox,'zone_entity');index=combo.findData('dynamic/boss/boss/0');self.assertGreaterEqual(index,0);combo.setCurrentIndex(index)
                dialog.findChild(QDialogButtonBox).button(QDialogButtonBox.StandardButton.Ok).click()
            QTimer.singleShot(0,select);edit_zone(win,win.doc.data['triggers'][0],'light');after=win.doc.snapshot();self.valid(after)
            self.assertEqual(after['scenes'][0]['triggers'][0]['light_zone']['entity'],'dynamic/boss/boss/0')
            win.undo_project();self.assertEqual(win.doc.snapshot(),before);win.redo_project();self.assertEqual(win.doc.snapshot(),after)
        finally:win.doc=None;win.close();self.app.processEvents()

    def test_bad_or_executable_asset_rejected_and_old_identity_preserved(self):
        case=library_tests.ContentLibraries();case.setUp()
        try:
            expected='lib_'+hashlib.sha256(case.source.read_bytes()+json.dumps(['misc/templates/new.not',['newCrate']]).encode()).hexdigest()[:12]
            self.assertEqual(import_identity(case.source,'misc/templates/new.not',['newCrate']),expected)
            for payload,selected in (({'bad.ncp':b'bad'},['bad.ncp']),({'Bad.class':b'bad'},['Bad.class'])):
                source=case.ws.write('bad.nob',zip_bytes(payload))
                with self.assertRaises(ValueError):prepare_import(case.ws,source,None,[],case.base,selected)
            self.assertFalse(case.ws.output('content_packs').exists())
        finally:case.tearDown()

    def test_asset_only_import_is_reachable_from_qt(self):
        from rcm.editor.window import MainWindow
        from rcm.editor.content_libraries import open_import
        win=MainWindow(self.backend)
        try:
            with tempfile.TemporaryDirectory(dir=ROOT/'build/tests') as tmp:
                source=Path(tmp)/'paths.nob';source.write_bytes(zip_bytes({'camera/QuietTurn.ncp':data_path()}))
                running=[True]
                def select():
                    if not running[0]:return
                    dialogs=[d for d in win.findChildren(QDialog) if d.findChild(QTreeWidget,'library_templates')]
                    if not dialogs:QTimer.singleShot(10,select);return
                    dialog=dialogs[0];running[0]=False
                    tree=dialog.findChild(QTreeWidget,'library_templates');tree.topLevelItem(0).child(0).setCheckState(0,Qt.CheckState.Checked)
                    dialog.findChild(QDialogButtonBox).button(QDialogButtonBox.StandardButton.Ok).click()
                record=dict(templates=[],entries=[dict(extension='.ncp')])
                with patch('rcm.editor.content_libraries.QFileDialog.getOpenFileName',return_value=(str(source),'')),patch('rcm.content_libraries.import_content',return_value=record) as imported,patch.object(QMessageBox,'information'),patch.object(QMessageBox,'warning') as warning:
                    QTimer.singleShot(0,select);open_import(win)
                    running[0]=False;warning.assert_not_called()
                self.assertEqual(imported.call_args.args[2:],(None,[],['camera/QuietTurn.ncp']))
        finally:win.doc=None;win.close();self.app.processEvents()
